/* From Uiverse.io by Yaya12085 - Tags: input, search */
.__UIV_SCOPE__ .input-container {
  position: relative;
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .input {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  border: none;
  outline: none;
  padding: 18px 16px;
  background-color: transparent;
  cursor: pointer;
  transition: all .5s ease-in-out;
}

.__UIV_SCOPE__ .input::placeholder {
  color: transparent;
}

.__UIV_SCOPE__ .input:focus::placeholder {
  color: rgb(131, 128, 128);
}

.__UIV_SCOPE__ .input:focus,.__UIV_SCOPE__ .input:not(:placeholder-shown) {
  background-color: #fff;
  border: 1px solid rgb(98, 0, 255);
  width: 290px;
  cursor: none;
  padding: 18px 16px 18px 40px;
}

.__UIV_SCOPE__ .icon {
  position: absolute;
  left: 0;
  top: 0;
  height: 40px;
  width: 40px;
  background-color: #fff;
  border-radius: 10px;
  z-index: -1;
  fill: rgb(98, 0, 255);
  border: 1px solid rgb(98, 0, 255);
}

.__UIV_SCOPE__ .input:hover + .icon {
  transform: rotate(360deg);
  transition: .2s ease-in-out;
}

.__UIV_SCOPE__ .input:focus + .icon,.__UIV_SCOPE__ .input:not(:placeholder-shown) + .icon {
  z-index: 0;
  background-color: transparent;
  border: none;
}
